public class CommandLineRunner_createOptions_TriageGen2Test {

    private CommandLineRunner runner;
    private CommandLineRunner.Flags flags;

    @Before
    public void setUp() throws Exception {
        // Since the constructor is protected and we need to control 'flags', 
        // we instantiate a subclass or use reflection to inject flags.
        runner = new CommandLineRunner(new String[]{}) {
            // Subclass to allow access to protected members if necessary
        };

        // We need to access the 'flags' field which is likely private/protected in CommandLineRunner
        // For the purpose of this test, we assume 'flags' is an instance variable of CommandLineRunner
        flags = mock(CommandLineRunner.Flags.class);
        setInternalState(runner, "flags", flags);
    }

    @Test
    public void testCreateOptions_FullCoverage() throws Exception {
        // Setup basic flags
        CompilationLevel mockLevel = mock(CompilationLevel.class);
        WarningLevel mockWarningLevel = mock(WarningLevel.class);
        FormattingOption mockFormatting = mock(FormattingOption.class);

        doReturn(mockLevel).when(flags).compilation_level;
        doReturn(mockWarningLevel).when(flags).warning_level;

        // Scenario 1: Debug true, generate_exports true, formatting present, closure true
        flags.debug = true;
        flags.generate_exports = true;
        flags.formatting = Collections.singletonList(mockFormatting);
        flags.process_closure_primitives = true;

        CompilerOptions options = runner.createOptions();

        // Verify CompilationLevel calls
        verify(mockLevel).setOptionsForCompilationLevel(options);
        verify(mockLevel).setDebugOptionsForCompilationLevel(options);

        // Verify exports
        assertThat(options.getGenerateExports()).isTrue();

        // Verify WarningLevel
        verify(mockWarningLevel).setOptionsForWarningLevel(options);

        // Verify Formatting
        verify(mockFormatting).applyToOptions(options);

        // Verify Closure
        assertThat(options.closurePass).isTrue();
        assertThat(options.getCodingConvention()).isInstanceOf(ClosureCodingConvention.class);
    }

    @Test
    public void testCreateOptions_MinimalCoverage() throws Exception {
        // Scenario 2: Debug false, generate_exports false, no formatting, closure false
        CompilationLevel mockLevel = mock(CompilationLevel.class);
        WarningLevel mockWarningLevel = mock(WarningLevel.class);

        doReturn(mockLevel).when(flags).compilation_level;
        doReturn(mockWarningLevel).when(flags).warning_level;

        flags.debug = false;
        flags.generate_exports = false;
        flags.formatting = Collections.emptyList();
        flags.process_closure_primitives = false;

        CompilerOptions options = runner.createOptions();

        // Verify Debug branch was skipped
        verify(mockLevel).setOptionsForCompilationLevel(options);
        // Note: verify(mockLevel, never()).setDebugOptionsForCompilationLevel(options) would be stricter

        // Verify exports not set (or logic skipped)
        // Based on code: if(flags.generate_exports) { options.setGenerateExports(...) }
        // If false, setGenerateExports is never called.

        // Verify WarningLevel
        verify(mockWarningLevel).setOptionsForWarningLevel(options);

        // Verify Closure
        assertThat(options.closurePass).isFalse();
    }

    /**
     * Helper to inject the mock flags into the protected/private field of CommandLineRunner
     */
    private void setInternalState(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getSuperclass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }
}
